function ui(k){return (UI[mode]&&UI[mode][k]) || UI.en[k] || k;}
function escapeHTML(s){return String(s ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function normalize(s){return String(s||'').toLowerCase().normalize('NFKC');}
function clip(s,n=240){s=String(s||''); return s.length>n?s.slice(0,n).trim()+'…':s;}
function dual(en, ne){ return mode==='ne' ? escapeHTML(ne||en) : escapeHTML(en); }
function val(obj,enKey,neKey){return mode==='ne' ? (obj[neKey]||obj[enKey]) : obj[enKey];}
function highlight(text, query=''){
  let safe=escapeHTML(text);
  const q=String(query||'').trim();
  if(!q) return safe;
  const terms=q.split(/\s+/).filter(Boolean).slice(0,6).map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));
  if(!terms.length) return safe;
  return safe.replace(new RegExp(`(${terms.join('|')})`,'gi'),'<mark>$1</mark>');
}
function textFor(obj,key){ return mode==='en' ? obj[key] : (obj[key+'Ne'] || obj[key]); }
function htmlFor(en, ne){ return dual(en, ne); }
function applyStatic(){
  document.documentElement.lang = mode==='ne' ? 'ne' : 'en';
  document.body.classList.toggle('lang-ne', mode==='ne');
  $$('[data-i18n]').forEach(el=>{ el.innerHTML = escapeHTML(ui(el.dataset.i18n)); });
  $$('[data-i18n-placeholder]').forEach(el=>{ el.placeholder = ui(el.dataset.i18nPlaceholder); });
  $('#languageNote').innerHTML = escapeHTML(ui('languageNote'));
  $$('.lang-btn').forEach(b=>b.classList.toggle('active', b.dataset.lang===mode));
}
function initMenu(){
  const btn=$('.menu-toggle'), nav=$('.nav-links');
  btn.addEventListener('click',()=>{const open=nav.classList.toggle('open');btn.setAttribute('aria-expanded',open);});
  $$('.nav-links a').forEach(a=>a.addEventListener('click',()=>nav.classList.remove('open')));
}
function initLanguage(){
  $$('.lang-btn').forEach(btn=>btn.addEventListener('click',()=>{mode=btn.dataset.lang; localStorage.setItem('budgetLangMode', mode); renderAll();}));
}
function renderHeroMetrics(){
  $('#heroTotal').textContent=`${nf.format(DATA.budget.total)}B`;
  $('#heroMetrics').innerHTML=DATA.budget.allocation.map(a=>`<div><small>${dual(a.label,a.labelNe)}</small><strong>${a.share}%</strong></div>`).join('');
}
function renderExplainers(){
  $('#explainers').innerHTML=DATA.plainCards.map((c,i)=>`<article class="info-card reveal" style="animation-delay:${i*.06}s"><h3>${dual(c.title,c.titleNe)}</h3><p>${highlight(textFor(c,'text'), '')}</p></article>`).join('');
}
function drawAllocationChart(){
  const canvas=$('#allocationChart'); if(!canvas) return;
  const ctx=canvas.getContext('2d'); const ratio=devicePixelRatio||1; const cssW=canvas.clientWidth||560, cssH=320;
  canvas.width=cssW*ratio; canvas.height=cssH*ratio; ctx.scale(ratio,ratio); ctx.clearRect(0,0,cssW,cssH);
  const cx=cssW*.28, cy=cssH*.48, r=Math.min(cssW,cssH)*.28; let start=-Math.PI/2;
  DATA.budget.allocation.forEach((item,i)=>{const slice=(item.share/100)*Math.PI*2; ctx.beginPath(); ctx.moveTo(cx,cy); ctx.arc(cx,cy,r,start,start+slice); ctx.closePath(); ctx.fillStyle=colors[i]; ctx.fill(); start+=slice;});
  ctx.beginPath(); ctx.arc(cx,cy,r*.58,0,Math.PI*2); ctx.fillStyle='rgba(255,248,239,.95)'; ctx.fill();
  ctx.fillStyle='#191713'; ctx.font='900 21px system-ui'; ctx.textAlign='center'; ctx.fillText('NPR',cx,cy-8); ctx.font='800 20px system-ui'; ctx.fillText(`${nf.format(DATA.budget.total)}B`,cx,cy+20);
  const max=Math.max(...DATA.budget.allocation.map(d=>d.amount));
  DATA.budget.allocation.forEach((item,i)=>{const label=mode==='en'?item.label:item.labelNe; const x=cssW*.58,y=48+i*68,w=(cssW*.35)*(item.amount/max); ctx.fillStyle='rgba(0,0,0,.07)'; roundRect(ctx,x,y,cssW*.34,22,11);ctx.fill(); ctx.fillStyle=colors[i];roundRect(ctx,x,y,w,22,11);ctx.fill(); ctx.fillStyle='#191713';ctx.font='800 13px system-ui';ctx.textAlign='left';ctx.fillText(label,x,y-8);ctx.fillStyle='#70685e';ctx.font='700 12px system-ui';ctx.fillText(`${nf.format(item.amount)}B · ${item.share}%`,x+w+8,y+16);});
  $('#allocationLegend').innerHTML=DATA.budget.allocation.map((item,i)=>`<div class="legend-item"><span class="dot" style="background:${colors[i]}"></span><span>${dual(item.label,item.labelNe)}: <strong>${item.share}%</strong></span></div>`).join('');
}
function roundRect(ctx,x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();}
function renderSources(){
  const max=Math.max(...DATA.budget.sources.map(s=>s.amount));
  $('#sourceBars').innerHTML=DATA.budget.sources.map((s,i)=>`<div class="source-bar"><span class="bar-fill" style="width:${(s.amount/max)*100}%;background:${colors[i%colors.length]}"></span><strong>${dual(s.label,s.labelNe)}</strong><span>NPR ${nf.format(s.amount)}B</span></div>`).join('');
  $('#gapNote').innerHTML=mode==='en'?`Revenue and foreign grants leave a financing gap of <strong>NPR ${nf.format(DATA.budget.gap)}B</strong>, covered by foreign loans and domestic borrowing.`:`राजस्व र वैदेशिक अनुदानपछि बाँकी <strong>NPR ${nf.format(DATA.budget.gap)}B</strong> gap वैदेशिक ऋण र आन्तरिक ऋणबाट पूरा गर्ने देखिन्छ।`;
  $('#federalNote').textContent=mode==='en'?DATA.budget.federalNote:DATA.budget.federalNoteNe;
  $('#transferTable').innerHTML=`<thead><tr><th>${ui('grantType')}</th><th>${ui('provinces')}</th><th>${ui('localLevels')}</th><th>${ui('total')}</th></tr></thead><tbody>`+DATA.budget.transfers.map(r=>`<tr><td>${dual(r.grant,r.grantNe)}</td><td>NPR ${nf.format(r.provinces)}B</td><td>NPR ${nf.format(r.local)}B</td><td><strong>NPR ${nf.format(r.provinces+r.local)}B</strong></td></tr>`).join('')+`</tbody>`;
}
function renderChips(container,categories,active,onClick,kind='sector'){
  container.innerHTML=['All',...categories].map(cat=>`<button class="btn chip-btn ${cat===active?'active':''}" data-chip="${escapeHTML(cat)}">${cat==='All'?ui('all'):dual(cat, kind==='finance' ? (DATA.financeSections.find(x=>x.category===cat)?.categoryNe || cat) : (DATA.sectors.find(x=>x.category===cat)?.categoryNe || cat))}</button>`).join('');
  $$('[data-chip]',container).forEach(btn=>btn.addEventListener('click',()=>onClick(btn.dataset.chip)));
}
function renderSectors(){
  const cats=[...new Set(DATA.sectors.map(s=>s.category))]; renderChips($('#sectorChips'),cats,activeSector,cat=>{activeSector=cat;renderSectors();},'sector');
  const q=normalize($('#sectorSearch').value); const rawQ=$('#sectorSearch').value;
  const sectors=DATA.sectors.filter(s=>{const inCat=activeSector==='All'||s.category===activeSector; const hay=normalize(`${s.title} ${s.titleNe} ${s.summary} ${s.summaryNe} ${s.amounts.join(' ')} ${s.body}`); return inCat && (!q || hay.includes(q));});
  $('#sectorGrid').innerHTML=sectors.map(s=>`<article class="glass-card sector-card" tabindex="0" data-sector="${s.number}"><span class="num">${s.number}</span><span class="pill">${dual(s.category,s.categoryNe)}</span><h3>${dual(s.title,s.titleNe)}</h3><p class="card-excerpt">${highlight(clip(textFor(s,'summary'),300), rawQ)}</p><div class="amount-tags">${(s.amounts||[]).slice(0,4).map(a=>`<span>${escapeHTML(a)}</span>`).join('')}</div><span class="read-more">${ui('readMore')}</span></article>`).join('')||`<p class="note">${ui('noSectors')}</p>`;
  $$('.sector-card').forEach(card=>{const open=()=>showDetail('sector',Number(card.dataset.sector)); card.addEventListener('click',open); card.addEventListener('keydown',e=>{if(e.key==='Enter')open();});});
}
function renderFinance(){
  const cats=[...new Set(DATA.financeSections.map(s=>s.category))]; renderChips($('#financeChips'),cats,activeFinance,cat=>{activeFinance=cat;renderFinance();},'finance');
  const q=normalize($('#financeSearch').value), rawQ=$('#financeSearch').value;
  const rows=DATA.financeSections.filter(s=>{const inCat=activeFinance==='All'||s.category===activeFinance; const hay=normalize(`${s.number} ${s.title} ${s.titleNe} ${s.summary} ${s.summaryNe} ${s.body} ${s.bodyNe||''}`); return inCat && (!q || hay.includes(q));});
  $('#financeList').innerHTML=rows.map(s=>`<article class="clause-item" data-clause="${s.number}"><div class="clause-no">${s.number}</div><div><h3>${dual(s.title,s.titleNe)}</h3><p class="card-excerpt">${highlight(clip(textFor(s,'summary'),240),rawQ)}</p><span class="read-more">${ui('readMore')}</span></div><span class="pill clause-tag">${dual(s.category,s.categoryNe)}</span></article>`).join('')||`<p class="note">${ui('noClauses')}</p>`;
  $$('.clause-item').forEach(row=>row.addEventListener('click',()=>showDetail('finance',Number(row.dataset.clause))));
}
function renderTariffs(){
  const q=normalize($('#tariffSearch').value), rawQ=$('#tariffSearch').value;
  let rows=DATA.tariffs.filter(r=>{const hasRate=Boolean((r.rate||'').trim()); if(tariffRateFilter==='has-rate'&&!hasRate)return false; if(tariffRateFilter==='no-rate'&&hasRate)return false; const hay=normalize(`${r.code} ${r.description} ${r.rate} ${r.group} ${r.annex}`); return !q||hay.includes(q);});
  $('#tariffCount').textContent=`${nf.format(rows.length)} ${ui('rowsShown')}`; rows=rows.slice(0,350);
  $('#tariffTable').innerHTML=`<thead><tr><th>${ui('hsCode')}</th><th>${ui('description')}</th><th>${ui('rate')}</th><th>${ui('group')}</th></tr></thead><tbody>`+rows.map(r=>`<tr><td><strong>${highlight(r.code,rawQ)}</strong></td><td>${highlight(r.description,rawQ)}</td><td>${highlight(r.rate||'—',rawQ)}</td><td>${escapeHTML(clip(r.group||r.annex||'—',110))}</td></tr>`).join('')+`</tbody>`;
}
function setupTariffButtons(){ $$('.tariff-tools [data-rate]').forEach(btn=>btn.addEventListener('click',()=>{tariffRateFilter=btn.dataset.rate; $$('.tariff-tools [data-rate]').forEach(b=>b.classList.toggle('active',b===btn)); renderTariffs();})); }
function buildSearchChunks(){ searchChunks=[]; DATA.docs.forEach(doc=>{doc.body.split(/\n{2,}|\n(?=###?\s)|\n(?=\*\*\d+)/g).map(x=>x.trim()).filter(x=>x.length>35).forEach((line,i)=>{const clean=line.replace(/^#+\s*/,'').replace(/\|\s*---.*$/gm,'').replace(/\*\*/g,''); if(clean.length>35) searchChunks.push({doc:doc.title,docId:doc.id,language:doc.language,type:doc.type,index:i,text:clean});});}); }
function renderGlobalSearch(){
  const q=$('#globalSearch').value.trim(), box=$('#globalResults'); if(!q){box.innerHTML=`<p class="note">${ui('searchEmpty')}</p>`; return;}
  const terms=normalize(q).split(/\s+/).filter(Boolean), scored=[]; for(const c of searchChunks){const hay=normalize(c.text); let score=0; terms.forEach(t=>{if(hay.includes(t))score+=t.length>2?3:1;}); if(score)scored.push({...c,score});}
  scored.sort((a,b)=>b.score-a.score||a.text.length-b.text.length);
  box.innerHTML=scored.slice(0,20).map(r=>`<article class="result-card"><span class="pill">${escapeHTML(r.type)} · ${escapeHTML(r.language)}</span><h3>${escapeHTML(r.doc)}</h3><p>${highlight(clip(r.text,420),q)}</p><button class="btn ghost open-doc" data-doc="${r.docId}" data-query="${escapeHTML(q)}">${ui('openDoc')}</button></article>`).join('')||`<p class="note">${ui('noMatches')}</p>`;
  $$('.open-doc').forEach(btn=>btn.addEventListener('click',()=>{$('#docSelect').value=btn.dataset.doc; $('#docSearch').value=btn.dataset.query; renderDoc(); location.hash='library';}));
}
function setupLibrary(){
  const select=$('#docSelect'); select.innerHTML=DATA.docs.map(d=>`<option value="${d.id}">${escapeHTML(d.title)} · ${escapeHTML(d.language)}</option>`).join('');
  select.addEventListener('change',renderDoc); $('#docSearch').addEventListener('input',renderDoc); $('#downloadDoc').addEventListener('click',()=>{const doc=DATA.docs.find(d=>d.id===$('#docSelect').value); const blob=new Blob([doc.body],{type:'text/markdown;charset=utf-8'}); const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download=`${doc.id}.md`; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);});
}
function chooseDefaultDoc(){ $('#docSelect').value = mode==='ne' ? 'speech_ne' : 'speech_en'; }
function markdownToHtml(md,query=''){
  const lines=md.split('\n'); const out=[]; let para=[],table=[],list=[];
  const flushPara=()=>{if(para.length){out.push(`<p>${formatInline(para.join(' '),query)}</p>`);para=[];}};
  const flushList=()=>{if(list.length){out.push(`<ul>${list.map(x=>`<li>${formatInline(x,query)}</li>`).join('')}</ul>`);list=[];}};
  const flushTable=()=>{if(table.length){const rows=table.filter(l=>!/\|\s*-/.test(l)).map(l=>l.trim().replace(/^\||\|$/g,'').split('|').map(c=>c.trim())); if(rows.length){const head=rows[0],body=rows.slice(1); out.push(`<div class="table-wrap"><table><thead><tr>${head.map(c=>`<th>${formatInline(c,query)}</th>`).join('')}</tr></thead><tbody>${body.map(r=>`<tr>${r.map(c=>`<td>${formatInline(c,query)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);} table=[];}};
  for(const raw of lines){const line=raw.trim(); if(!line){flushPara();flushList();flushTable();continue;} if(line.startsWith('|')){flushPara();flushList();table.push(line);continue;} flushTable(); const h=line.match(/^(#{1,3})\s+(.+)/); if(h){flushPara();flushList();const level=h[1].length;out.push(`<h${level}>${formatInline(h[2],query)}</h${level}>`);continue;} if(line.startsWith('>')){flushPara();flushList();out.push(`<blockquote>${formatInline(line.replace(/^>\s?/,''),query)}</blockquote>`);continue;} if(/^[-*]\s+/.test(line)){flushPara();list.push(line.replace(/^[-*]\s+/,''));continue;} para.push(line);} flushPara();flushList();flushTable();return out.join('\n');
}
function formatInline(s,query=''){let safe=highlight(String(s).replace(/`([^`]+)`/g,'$1'),query);safe=safe.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>');return safe;}
function renderDoc(){
  const doc=DATA.docs.find(d=>d.id===$('#docSelect').value)||DATA.docs[0], q=$('#docSearch').value.trim(); let body=doc.body;
  if(q){const terms=normalize(q).split(/\s+/).filter(Boolean); const blocks=doc.body.split(/\n{2,}/).filter(block=>terms.some(t=>normalize(block).includes(t))); body=blocks.length?`# ${ui('searchMatches')} ${doc.title}\n\n`+blocks.slice(0,80).join('\n\n---\n\n'):`# No matches\n\n${ui('noDocMatches')} “${q}” in this document.`;}
  $('#docMeta').textContent=`${doc.type} · ${doc.language} · ${nf.format(doc.body.length)} ${ui('characters')}`; $('#docContent').innerHTML=markdownToHtml(body,q);
}
function showDetail(type,id){
  const modal=$('#detailModal'); let item,title,body,meta,titleNe,bodyNe;
  if(type==='sector'){item=DATA.sectors.find(s=>s.number===id); title=`${item.number}. ${item.title}`; titleNe=`${item.number}. ${item.titleNe||item.title}`; body=item.body; bodyNe=item.summaryNe; meta=dual(item.category,item.categoryNe);} else {item=DATA.financeSections.find(s=>s.number===id); title=`${item.number}. ${item.title}`; titleNe=`${item.number}. ${item.titleNe||item.title}`; body=item.body; bodyNe=item.bodyNe||item.summaryNe; meta=dual(item.category,item.categoryNe);}
  let content='';
  if(mode==='ne') content=`<span class="pill">${meta}</span><h2>${escapeHTML(titleNe)}</h2><div class="modal-body-text markdown-body">${markdownToHtml(bodyNe||body)}</div>`;
  else content=`<span class="pill">${meta}</span><h2>${escapeHTML(title)}</h2><div class="modal-body-text markdown-body">${markdownToHtml(body)}</div>`;
  $('#modalBody').innerHTML=content; if(typeof modal.showModal==='function') modal.showModal(); else modal.setAttribute('open',''); document.body.classList.add('no-scroll');
}
function initModal(){ const modal=$('#detailModal'); $('.modal-close').addEventListener('click',()=>{modal.close();document.body.classList.remove('no-scroll');}); modal.addEventListener('click',e=>{if(e.target===modal){modal.close();document.body.classList.remove('no-scroll');}}); modal.addEventListener('close',()=>document.body.classList.remove('no-scroll')); }
function initBackTop(){ const btn=$('#toTop'); window.addEventListener('scroll',()=>btn.classList.toggle('show',scrollY>600)); btn.addEventListener('click',()=>scrollTo({top:0,behavior:'smooth'})); }
function bindInputs(){ $('#sectorSearch').addEventListener('input',renderSectors); $('#financeSearch').addEventListener('input',renderFinance); $('#tariffSearch').addEventListener('input',renderTariffs); $('#globalSearch').addEventListener('input',renderGlobalSearch); window.addEventListener('resize',drawAllocationChart); }
function renderAll(){ applyStatic(); renderHeroMetrics(); renderExplainers(); drawAllocationChart(); renderSources(); renderSectors(); renderFinance(); renderTariffs(); renderGlobalSearch(); chooseDefaultDoc(); renderDoc(); }
function init(){ initMenu(); initLanguage(); setupTariffButtons(); buildSearchChunks(); setupLibrary(); initModal(); initBackTop(); bindInputs(); renderAll(); }
document.addEventListener('DOMContentLoaded', init);
